entries[1220398] = { ["name"] = "Doppelwums-Schuss", ["text"] = "300 Meter Reichweite\nSofort\nZee feuert ein explosive, großkalibrige Patrone auf einen zufälligen Spielercharakter, fügt dem nächsten Spielercharakter 26832278 körperlichen Schaden zu und belegt ihn mit ' Perforierende Wunde '. Alle anderen Ziele erleiden bis zu 26832278 körperlichen Schaden, der durch die Gesamtschadensmitigation des nächsten Spielercharakters abgeschwächt wird.\n\nGetroffene Instabile Kriecherminen detonieren und getroffene Spielercharaktere werden für 2 Sek. betäubt. Außerdem wird dem ursprünglichen Ziel ein ' Explosiver Sprengkörper ' angeheftet." }
entries[1220399] = { ["name"] = "Doppelwums-Schuss", ["text"] = "300 Meter Reichweite\nSofort\nZee feuert ein explosive, großkalibrige Patrone auf einen zufälligen Spielercharakter, fügt dem nächsten Spielercharakter 26832278 körperlichen Schaden zu und belegt ihn mit ' Perforierende Wunde '. Alle anderen Ziele erleiden bis zu 26832278 körperlichen Schaden, der durch die Gesamtschadensmitigation des nächsten Spielercharakters abgeschwächt wird.\n\nGetroffene Instabile Kriecherminen detonieren und getroffene Spielercharaktere werden für 2 Sek. betäubt. Außerdem wird dem ursprünglichen Ziel ein ' Explosiver Sprengkörper ' angeheftet." }
