entries[1220413] = { ["name"] = "Turbogeladen", ["text"] = "Sofort\nAlle 6 Sek. versetzt Ihr Eurem Ziel und 1 Gegner in der Nähe einen Schock und fügt ihnen ( 107 * 1 ) Naturschaden zu.\n\nDurch den Einsatz von 30 Zaubern werdet Ihr für 15 Sek. 'Turbogeladen', was die Häufigkeit Eurer Schocks verdoppelt und sie zu Gigaschocks macht, die stattdessen ( 107 * 3 * 1 ) Naturschaden verursachen." }
