entries[1220481] = { ["name"] = "Schrottmaestros fauliger Müll", ["text"] = "100 Meter Reichweite\nSofort\nKehrt die Polarität des Magneten um, um vergrabenen Müll gewaltsam zu recyceln, was Eurem Ziel [Quellwert]* 1 Seuchenschaden pro Ladung zufügt. Verbleibende Virulenz fügt 5 Gegnern in der Nähe im Verlauf von 6 Sek. 10% des verursachten Schadens zu.", ["unresolvedValues"] = true }
