entries[1220487] = { ["name"] = "Protokoll: Reinigen", ["text"] = "300 Meter Reichweite\nSofort\nDie Plexuswache wechselt den Standort, stößt dabei Spielercharaktere zurück und aktiviert ' Arkanomatrixatomisierer '. Der Atomisierer schwebt langsam durch die Kammer und atomisiert dabei alle Spielercharaktere sowie instabile Manifestation, mit denen er dabei in Kontakt kommt.\n\nHat sie ihre neue Position erreicht, kanalisiert die Plexuswache ' Protokoll: Reinigen ' und erhält einen Schaden absorbierenden Schild. Wird der Schild durchbrochen, wird der Zauber ' Protokoll: Reinigen ' unterbrochen." }
entries[1220488] = { ["name"] = "Sanikopter der Düsternisverschmolzenen", ["text"] = "45 Meter Reichweite\nSofort 2 min Abklingzeit\nWeist den Sanikopter an, sich an Euer Ziel zu heften. Dadurch wird beim Ziel 483 Schaden absorbiert und seine Vielseitigkeit wird 15 Sek. lang um 55 erhöht.\n\nSolange der Sanikopter an das Ziel geheftet bleibt, besteht bei Euren Heilzaubern die Chance, den Sanikopter wieder aufzutanken und dem Ziel diese Boni erneut zu gewähren." }
entries[1220489] = { ["name"] = "Protokoll: Reinigen", ["text"] = "300 Meter Reichweite\nWirken in 5 sek.\nDie Plexuswache wechselt den Standort, stößt dabei Spielercharaktere zurück und aktiviert ' Arkanomatrixatomisierer '. Der Atomisierer schwebt langsam durch die Kammer und atomisiert dabei alle Spielercharaktere sowie instabile Manifestation, mit denen er dabei in Kontakt kommt.\n\nHat sie ihre neue Position erreicht, kanalisiert die Plexuswache ' Protokoll: Reinigen ' und erhält einen Schaden absorbierenden Schild. Wird der Schild durchbrochen, wird der Zauber ' Protokoll: Reinigen ' unterbrochen." }
