entries[1220736] = { ["name"] = "Mysteriöse Wiederbelebung", ["text"] = "Sofort\nReagenzien:\nTrank der mysteriösen Wiederbelebung\nNach dem Plündern: Erhöht Eure Gesundheitsregeneration um 3%.\n\nHält 30 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht." }
entries[1220739] = { ["name"] = "Überladene Barriere", ["text"] = "Frost ( Frostmagier )\nEure Barrieren absorbieren 80% mehr Schaden und haben einen zusätzlichen Effekt, halten jedoch nur 4 Sek. lang an.\n\nEisbarriere\nWenn die Barriere vollständig absorbiert wurde, erleiden Gegner innerhalb von 10 Metern (650% der Zaubermacht) Frostschaden und werden 4 Sek. lang um 70% verlangsamt.\n\nArkan, Feuer\nEure Barrieren absorbieren 100% mehr Schaden und haben einen zusätzlichen Effekt, halten jedoch nur 4 Sek. lang an. [ Frost : Eisbarriere\nWenn die Barriere vollständig absorbiert wurde, erleiden Gegner innerhalb von 10 Metern (650% der Zaubermacht) Frostschaden und werden 4 Sek. lang um 70% verlangsamt / Feuer : Lodernde Barriere\nReflektiert 40% des absorbierten Schadens /\n\nArkan\n' Prismatische Barriere\n'Wenn die Barriere vollständig absorbiert wurde, gewährt Euer nächstes 'Blinzeln' oder 'Flimmern' innerhalb von 15 Sek. 3 Sek. lang Unsichtbarkeit und Immunität gegen Schaden. Die Schadensverringerung wird aufgehoben, wenn die Unsichtbarkeit endet ]" }
