entries[1220981] = { ["name"] = "Protokoll: Reinigen", ["text"] = "100 Energie\nKanalisiert (Wirken in 2 min)\nDie Plexuswache wechselt den Standort, stößt dabei Spielercharaktere zurück und aktiviert ' Arkanomatrixatomisierer '. Der Atomisierer schwebt langsam durch die Kammer und atomisiert dabei alle Spielercharaktere sowie instabile Manifestation, mit denen er dabei in Kontakt kommt.\n\nHat sie ihre neue Position erreicht, kanalisiert die Plexuswache ' Protokoll: Reinigen ' und erhält einen Schaden absorbierenden Schild. Wird der Schild durchbrochen, wird der Zauber ' Protokoll: Reinigen ' unterbrochen." }
entries[1220982] = { ["name"] = "Protokoll: Reinigen", ["text"] = "100 Energie\nWirken in 5 sek.\nDie Plexuswache wechselt den Standort, stößt dabei Spielercharaktere zurück und aktiviert ' Arkanomatrixatomisierer '. Der Atomisierer schwebt langsam durch die Kammer und atomisiert dabei alle Spielercharaktere sowie instabile Manifestation , mit denen er dabei in Kontakt kommt.\n\nHat sie ihre neue Position erreicht, kanalisiert die Plexuswache ' Protokoll: Reinigen ' und erhält einen Schaden absorbierenden Schild. Wird der Schild durchbrochen, wird der Zauber ' Protokoll: Reinigen ' unterbrochen." }
