entries[1221061] = { ["name"] = "Xal'ataths Geschenk", ["text"] = "100 Meter Reichweite\nSofort\nDie Leerenabgesandte spricht ein dunkles Gebet. Wenn das Gebet abgeschlossen wurde, erhalten Kreaturen in der Nähe ' Xal'ataths Geschenk ', welches 20 Sek. lang ihren verursachten Schaden um bis zu 50% erhöht und ihren erlittenen Schaden um bis zu 100% verringert, basierend darauf, wie viel vom Schild der Leerenabgesandten verbleibt.\n\nWenn die Leerenabgesandte besiegt wird, werden die Spielercharaktere ermächtigt, was ihnen 30 Sek. lang 20% Vielseitigkeit sowie 30% Zauber- und Fähigkeitsabklingzeitrate gewährt." }
entries[1221063] = { ["name"] = "Xal'ataths Geschenk", ["text"] = "Sofort\nXal'atath lässt Kugeln kosmischer Energie herabregnen, die versuchen, Kreaturen in der Nähe ' Xal'ataths Geschenk ' zu gewähren, wodurch sich deren verursachter Schaden um 5% erhöht und deren erlittener Schaden um 10% verringert. Dieser Effekt hält 20 Sek. lang an und ist stapelbar.\n\nWenn Spielercharaktere diese Kugeln aufhalten, können sie diese Macht beanspruchen, was ihr Tempo und ihre Bewegungsgeschwindigkeit für 30 Sek. um 2% erhöht. Dieser Effekt ist stapelbar." }
