entries[1221790] = { ["name"] = "Galvanisierte Bosheit", ["text"] = "Unbegrenzte Reichweite\nSofort\nTorq knistert vor Elektrizität und belegt alle 5 Sek. alle Spielcharaktere innerhalb von 60 Metern mit ' Galvanisierte Bosheit ', was diesen 15 Sek. lang alle 1 Sek. 13428 Naturschaden zufügt. Dieser Effekt ist stapelbar." }
