entries[1222202] = { ["name"] = "Arkane Verbrennung", ["text"] = "100 Meter Reichweite\nSofort\nDie Verbrennung fügt Spielercharakteren im Effektbereich alle 1.5 Sek. 2909339 Arkanschaden zu und reduziert ihre Bewegungsgeschwindigkeit um 40%." }
