entries[1222232] = { ["name"] = "Zorn des Verschlingers", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus schleudert Kugeln aus gieriger Leere auf mehrere Positionen, die allen Spielercharakteren 5621532 kosmischen Schaden zufügen, wenn sie nicht abgefangen werden.\n\nAdarus fokussiert seinen Blick auf Spielercharaktere, die diese Kugeln abgefangen haben, greift sie kontinuierlich mit ' Verschlingen ' an und erhöht ihren erlittenen körperlichen Schaden um 100%.\n\nBei Entfernung wird ' Zorn des Verschlingers ' auf einen Spielercharakter in der Nähe übertragen und fügt allen Spielercharakteren 2108075 kosmischen Schaden zu." }
entries[1222234] = { ["name"] = "Vantusrune: Lorenhall", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nStellt Euch einmal pro Woche auf die Energien des anvisierten Schlachtzugsbosses aus Lorenhall ein und erlangt folgende Aura:\n\nVantusrune: Befreiung von Lorenhall\nErhöht Eure Vielseitigkeit im Kampf gegen den entsprechenden Schlachtzugboss um 1500 . Der Effekt hält die ganze Woche lang an." }
entries[1222239] = { ["name"] = "Vantusrune: Lorenhall", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nStellt Euch einmal pro Woche auf die Energien des anvisierten Schlachtzugsbosses aus Lorenhall ein und erlangt folgende Aura:\n\nVantusrune: Befreiung von Lorenhall\nErhöht Eure Vielseitigkeit im Kampf gegen den entsprechenden Schlachtzugboss um 1700 . Der Effekt hält die ganze Woche lang an." }
entries[1222242] = { ["name"] = "Schwermutsbiss", ["text"] = "8 Meter Reichweite\nWirken in 1.55 sek.\nDer Kriecher beißt sein aktuelles Ziel und verursacht 36 Schattenschaden." }
entries[1222244] = { ["name"] = "Verschlingen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nAdarus entzieht die Essenz aller Spielercharaktere, die derzeit von '' betroffen sind, verursacht 3 kosmischen Schaden und absorbiert die nächste 20 erhaltene Heilung.\n\nDieser Ausbruch ruft ' Endloser Hunger ' hervor." }
entries[1222247] = { ["name"] = "Grässliches Gebrüll", ["text"] = "Wirken in 2.5 sek.\nDer Kriecher stößt ein Brüllen aus, fügt Spielercharakteren in der Nähe 10 Schattenschaden zu und erhöht den durch ' Grässliches Gebrüll ' erlittenen Schaden um 50%. Dieser Effekt ist stapelbar." }
entries[1222265] = { ["name"] = "Wilder Bund", ["text"] = "Sofort\nDer Meister und sein Tier werden von Wut erfüllt, wodurch sich ihr Angriffstempo 20 Sek. lang um 50% erhöht." }
entries[1222271] = { ["name"] = "Wyvernheulen", ["text"] = "Sofort\nIm Kampf beschwört Euer nächster 'Tötungsbefehl' alle 30 Sek. die Hilfe eines Wildtiers.\n\nWyvern\nEin Wyvern stürzt sich vom Himmel herab und stößt einen Kampfesschrei aus, der Euren Schaden sowie den Eurer Begleiter 15 Sek. lang um 10% erhöht.\n\nEber\nEin Eber stürmt 3-mal durch die gegnerischen Reihen und fügt dem Hauptziel (400% der Angriffskraft) körperlichen Schaden sowie bis zu 8 Gegnern in der Nähe (160% der Angriffskraft) Schaden zu.\n\nBär\nEin Bär stürzt sich ins Getümmel, reißt den Gegnern das Fleisch von den Knochen und fügt so bis zu 8 Gegnern in der Nähe im Verlauf von 10 Sek. (400% der Angriffskraft) Schaden zu." }
entries[1222275] = { ["name"] = "Hupen!", ["text"] = "Sofort 1.5 sek. Abklingzeit\nHupt, um allen zu zeigen, was Ihr gerade empfindet." }
entries[1222307] = { ["name"] = "Verschlingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus entzieht die Essenz aller Spielercharaktere, die derzeit von '' betroffen sind, verursacht 3 kosmischen Schaden und absorbiert die nächste 2305797 erhaltene Heilung.\n\nDieser Ausbruch ruft ' Endloser Hunger ' hervor." }
entries[1222310] = { ["name"] = "Endloser Hunger", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus schwächt sein Ziel, wodurch der durch ' Verschlingen ' erlittene Schaden und die Heilungsabsorption 1 Min. lang um 20% erhöht werden. Dieser Effekt ist stapelbar." }
entries[1222312] = { ["name"] = "Feurige Welle", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine feurige Hitzewelle, die von Leuchtendos Spontanverbrennungsmotor erzeugt wird, fügt Spielcharakteren bei Kontakt 60 Feuerschaden zu." }
