entries[1222542] = { ["name"] = "Egoüberprüfung", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek.\nGallywix verpasst seinem Ziel eine 4 er Tracht Prügel und verursacht mit jedem Treffer 80 körperlichen Schaden. Diese Schläge können nicht pariert oder ihnen ausgewichen werden.\n\nAußerdem werden 75 % des nicht mitigierten Schadens als ' Geprüftes Ego ' verursacht." }
entries[1222554] = { ["name"] = "Gleve werfen", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nVelaryn markiert Spielercharaktere und schleudert kurz darauf eine Gleve, die zwischen allen markierten Zielen hin und her springt.\n\nDer Aufprall fügt Spielercharakteren innerhalb von 9 Metern 30 Chaosschaden zu und belegt sie mit ' Brennende Wunde '." }
