entries[1222698] = { ["name"] = "Mordrausch", ["text"] = "Sofort\nSiegesserie! sorgt dafür, dass 'Froststoß' und 'Unaufhaltbarer Gletscher' pro Stapel eine Chance von 8% haben, 'Frostsichel' mit 30% Effektivität zu wirken. Wenn Eure Siegesserie! endet, verfallt Ihr in einen 'Mordrausch' und zaubert 'Frostsichel' mit 100% Effektivität, während Ihr 6 Sek. lang (6 * [Quellwert] astery)% Meisterschaft erlangt. 'Frostsichel' fügt außerdem dem ersten getroffenen Ziel 40% mehr Schaden zu.", ["unresolvedValues"] = true }
