entries[1222722] = { ["name"] = "Todesritterklassenset, Frost, 11.1, 4 Teile", ["text"] = "Sofort\nEure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Froststoß' und 'Unaufhaltbarer Gletscher' um 4% erhöht und bis zu 6-mal stapelbar ist. 'Froststoß' und 'Unaufhaltbarer Gletscher' haben eine Chance von 7%, Eure Siegesserie! zu entfernen." }
