entries[1223183] = { ["name"] = "Kollabierender Stern", ["text"] = "Unbegrenzte Reichweite\nWirken in 7 sek.\nAdarus schleudert eine kollabierende Sphäre kosmischer Energie auf den Spielercharakter, der aktuell von 'Zorn der Zwietracht' gebrandmarkt ist, und fügt allen Spielercharakteren 40 kosmischen Schaden zu.\n\nDer Einschlag hinterlässt in einem großen Bereich ' Drohendes Vergessen '." }
