entries[1223187] = { ["name"] = "Schrecken des Ödlands", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Er ist nicht weltverschlingend böse, nur missverstanden.\"\nVerkäufer:\nOm'sirik\nZone:\nK'aresh\nKosten:\n11.375" }
