entries[1223191] = { ["name"] = "Schrecken der Nacht", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Lasst Euch nicht von seinen leuchtenden Farben täuschen. Er kann sich an wirklich alles und jeden anschleichen.\"\nErfolg:\nSelbstjustiz\nKategorie:\nWar Within" }
